                    {/* Area Badge Label inside or next to box */}
                    {sideLenPixels > 8 && (
                      <text
                        x={boxX + sideLenPixels / 2}
                        y={topY + sideLenPixels / 2 + 3}
                        textAnchor="middle"
                        fontSize="9"
                        fill={strokeColor}
                        fontWeight="800"
                      >
                        {p.sqErr.toFixed(0)}
                      </text>
                    )}

                    {/* Vertical Residual Line */}
                    <line x1={sx} y1={syActual} x2={sx} y2={syPred} stroke={strokeColor} strokeWidth="2" />

